<script setup lang="ts">
import {ref,computed,onMounted,watch} from 'vue'
import {Heart,ArrowRight,Mail,Check,ArrowLeft} from 'lucide-vue-next'
import Paw from './Paw.vue'
import {db,fail,friendly} from '../lib/supabase'
import {user,profile,refreshProfile,logout,authReady} from '../lib/session'
import type {Settings} from '../lib/types'
const props=defineProps<{token:string;settings:Settings}>(),emit=defineEmits<{home:[];login:[]}>()
const card=ref<{display_name:string;personal_message:string;max_guests:number;claimed:boolean}|null>(null),loading=ref(true),opened=ref(false),busy=ref(false),error=ref(''),message=ref(''),email=ref(''),password=ref(''),name=ref(''),alias=ref(''),phone=ref(''),consent=ref(false),registered=ref(false),complete=ref(false)
const date=computed(()=>props.settings.date?new Date(props.settings.date).toLocaleDateString('es-ES',{day:'numeric',month:'long',year:'numeric',timeZone:'Europe/Madrid'}):'Muy pronto compartiremos la fecha')
function populate(){name.value=profile.value?.full_name||user.value?.user_metadata.full_name||card.value?.display_name||'';alias.value=profile.value?.alias||user.value?.user_metadata.alias||'';phone.value=profile.value?.phone||''}
async function load(){loading.value=true;error.value='';try{const {data,error:e}=await db.rpc('wedding_guest_postcard',{invite_token:props.token});fail(e);card.value=data;populate();if(data?.claimed)complete.value=true}catch(e){error.value=friendly(e)}finally{loading.value=false}}
async function claim(){if(!consent.value)throw new Error('Acepta el uso de tus datos para activar la invitación.');const {error:e}=await db.rpc('wedding_claim_guest_pass',{invite_token:props.token,guest_name:name.value,guest_alias:alias.value,guest_phone:phone.value,accept_data:consent.value});fail(e);await refreshProfile();complete.value=true;await db.auth.updateUser({data:{wedding_invite_token:null}})}
async function submit(){busy.value=true;error.value='';message.value='';try{if(!consent.value)throw new Error('Acepta el uso de tus datos para continuar.');if(user.value){await claim()}else{
 const {data,error:e}=await db.auth.signUp({email:email.value.trim(),password:password.value,options:{emailRedirectTo:location.origin+'/',data:{full_name:name.value,alias:alias.value,wedding_invite_token:props.token}}});fail(e)
 if(data.session){user.value=data.user;await claim()}else{registered.value=true;message.value='Revisa tu correo y confirma tu cuenta. Al volver, podrás activar tu invitación y personalizar tu perfil.'}
 }}catch(e){error.value=friendly(e)}finally{busy.value=false}}
watch(()=>[user.value?.id,authReady.value],()=>{if(authReady.value)void load()})
onMounted(()=>{void load()})
</script>
<template><main class="postcard-page"><a class="postcard-back" href="/" @click.prevent="emit('home')"><ArrowLeft :size="16"/> La web de la boda</a><span class="postcard-monogram">L <i>&</i> J</span><p v-if="loading" class="postcard-loading">Estamos preparando tu postal…</p><section v-else-if="!card" class="postcard-invalid"><Mail :size="36"/><h1>Esta postal no está disponible</h1><p>El enlace puede haber caducado, estar desactivado o haberse utilizado. Pide a Laura y Javier un enlace nuevo, o entra si ya tienes cuenta.</p><p v-if="error" class="error" role="alert">{{error}}</p><button class="btn" @click="emit('login')">Entrar a mi cuenta</button></section><template v-else><div v-if="!opened&&!complete" class="envelope-stage"><p class="eyebrow">HAY ALGO BONITO PARA TI</p><h1>{{card.display_name}},<br/><em>esta es tu invitación.</em></h1><button class="wedding-envelope" aria-label="Abrir mi postal de boda" @click="opened=true"><span class="envelope-paper"><span>LAURA & JAVIER</span><Heart :size="30"/></span><span class="envelope-flap"></span><span class="envelope-seal">L&J</span><span class="envelope-address">Para {{card.display_name}}</span></button><button class="text-link" @click="opened=true">Abrir nuestra postal <ArrowRight :size="17"/></button><p class="small">Un día especial. Nuestra gente favorita. Y tú.</p></div><div v-else class="postcard-layout"><article class="wedding-postcard"><div class="postcard-picture"><img src="/images/couple.png" alt="Laura y Javier en la playa"/><span>PARA GUARDAR SIEMPRE</span></div><div class="postcard-letter"><Paw/><p class="eyebrow">NOS CASAMOS</p><h1>Laura <i>&</i> Javier</h1><p class="postcard-date">{{date}}</p><p v-if="settings.location">{{settings.location}}</p><div class="postcard-rule"></div><h2>Para {{card.display_name}}</h2><p class="preserve dedication">{{card.personal_message||'No imaginamos este día sin ti. ¿Nos acompañas?'}}</p><p class="postcard-signature">Con todo nuestro cariño,<br/>Laura y Javier</p><span class="postcard-stamp"><Paw/> HECHO CON AMOR</span></div></article><section class="postcard-activation"><template v-if="complete"><Check :size="34"/><span class="eyebrow">YA TIENES TU SITIO</span><h2>¡Qué alegría contar contigo!</h2><p>Tu cuenta está lista. Puedes confirmar tu asistencia, proponer canciones y jugar con nuestro perrito.</p><button class="btn" @click="emit('home')">Entrar a la boda <ArrowRight :size="17"/></button></template><template v-else><span class="eyebrow">TU INVITACIÓN PERSONAL</span><h2>{{user?'Hazla tuya':'Tu sitio en esta historia'}}</h2><p>La invitación incluye hasta <b>{{card.max_guests}} {{card.max_guests===1?'persona':'personas'}}</b>, contándote a ti.</p><p v-if="user" class="small">Has entrado con {{user.email}}. <button class="text-link" @click="logout">Cambiar de cuenta</button></p><form v-if="!registered||user" @submit.prevent="submit"><label>Tu nombre y apellidos<input v-model="name" required minlength="2" maxlength="100" autocomplete="name"/></label><label>Tu alias para los juegos<input v-model="alias" required minlength="2" maxlength="24" autocomplete="nickname" placeholder="Como quieres que te llamemos"/></label><label v-if="!user">Correo al que te hemos invitado<input v-model="email" required type="email" autocomplete="email"/><small>Utiliza el mismo correo que facilitaste a los novios.</small></label><label v-if="!user">Elige una contraseña<input v-model="password" type="password" required minlength="10" autocomplete="new-password"/><small>Al menos 10 caracteres.</small></label><label v-else>Teléfono opcional<input v-model="phone" type="tel" maxlength="30" autocomplete="tel"/></label><label class="check"><input v-model="consent" type="checkbox" required/>Acepto que Laura y Javier usen mis datos para organizar la boda y guardar mis partidas. Elegiré mis preferencias de avisos en mi perfil.</label><button class="btn full" :disabled="busy||!authReady">{{busy?'Un momentito…':user?'Activar mi invitación':'Crear mi cuenta'}}<ArrowRight :size="16"/></button></form><div v-else class="postcard-check-mail"><Mail :size="28"/><h3>Te hemos reservado tu postal</h3><p>Busca el correo de confirmación, también en la carpeta de spam.</p></div><p v-if="message" class="success" role="status">{{message}}</p><p v-if="error" class="error" role="alert">{{error}}</p><button v-if="!user" class="text-link" @click="emit('login')">Ya tengo cuenta · Entrar</button></template></section></div></template></main></template>
